import os
procs = []
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    try:
        with open(f'/proc/{pid}/cmdline', 'rb') as f:
            cmdline = f.read().decode('utf-8', errors='ignore').replace('\x00',' ').strip()
        if 'run_ecommerce_analysis.py' in cmdline:
            procs.append((pid, cmdline))
    except Exception:
        continue
print('found', procs)
